#include "row_access.hpp"

#include <array>
#include <filesystem>
#include <fstream>

#include "gtest/gtest.h"

namespace livehd::physical {
namespace {
using enum Row_access;
// Template t0 of a two-row domino master: local row 0 horizontal, row 1 vertical.
constexpr std::array<Row_access, 2> kT0{horizontal, vertical};
// Rows generated by placement alternate N/FS from the bottom core row.
Orientation                         generated(size_t row) { return row % 2 ? Orientation::FS : Orientation::N; }
std::string                         json_file(const std::string& name, const std::string& text) {
  const auto path = std::filesystem::path(testing::TempDir()) / name;
  std::ofstream(path) << text;
  return path.string();
}
}  // namespace
TEST(RowAccess, StandInConventionAlternatesFromTheBottomCoreRow) {
  const Row_access_convention convention;
  EXPECT_EQ(convention.at(0), horizontal);
  EXPECT_EQ(convention.at(1), vertical);
  EXPECT_EQ(convention.at(6), horizontal);
  auto one_based       = convention;
  one_based.index_base = 1;
  EXPECT_EQ(one_based.at(0), vertical);
  EXPECT_EQ(one_based.at(1), horizontal);
  EXPECT_EQ(row_access_name(vertical), "vertical");
}
TEST(RowAccess, GeneratedRowsPutLocalRowZeroOnAnEvenRowAtBothParities) {
  const Row_access_convention convention;
  for (size_t start = 0; start < 6; ++start) {
    SCOPED_TRACE(start);
    EXPECT_EQ(placed_row_of_half(start, 2, 0, generated(start)) % 2, 0u);
    EXPECT_TRUE(row_access_matches(convention, start, generated(start), kT0));
    // The x mirror of the row orientation lands the same local rows.
    const auto mirror = generated(start) == Orientation::N ? Orientation::FN : Orientation::S;
    EXPECT_TRUE(row_access_matches(convention, start, mirror, kT0));
  }
}
TEST(RowAccess, AllNorthRowsAdmitOnlyOneStartParity) {
  const Row_access_convention convention;
  for (size_t start = 0; start < 6; ++start) {
    EXPECT_EQ(placed_row_of_half(start, 2, 0, Orientation::N), start);
    EXPECT_EQ(placed_row_of_half(start, 2, 1, Orientation::N), start + 1);
    EXPECT_EQ(row_access_matches(convention, start, Orientation::N, kT0), start % 2 == 0) << start;
  }
  auto one_based       = convention;
  one_based.index_base = 1;
  EXPECT_FALSE(row_access_matches(one_based, 0, Orientation::N, kT0));
  EXPECT_TRUE(row_access_matches(one_based, 1, Orientation::N, kT0));
}
TEST(RowAccess, FlippedFirstFrameHasNoCompatibleStartForTemplateZero) {
  const Row_access_convention convention;
  for (size_t start = 0; start < 6; ++start) {
    const auto o = start % 2 ? Orientation::N : Orientation::FS;
    EXPECT_FALSE(row_access_matches(convention, start, o, kT0)) << start;
  }
}
TEST(RowAccess, PlacedRowsOfTallerMastersAndRefusals) {
  EXPECT_EQ(placed_row_of_half(4, 3, 0, Orientation::S), 6u);
  EXPECT_EQ(placed_row_of_half(4, 3, 2, Orientation::FS), 4u);
  EXPECT_EQ(placed_row_of_half(4, 3, 1, Orientation::FN), 5u);
  EXPECT_THROW(placed_row_of_half(4, 2, 2, Orientation::N), std::invalid_argument);
  EXPECT_THROW(placed_row_of_half(4, 2, 0, Orientation::W), std::invalid_argument);
}
TEST(RowAccess, IdentityIsCanonicalJsonAndReadsBack) {
  const Row_access_convention stand_in;
  EXPECT_EQ(
      stand_in.identity(),
      R"({"schema":1,"name":"stand-in","version":"1","origin":"first_core_row","index_base":0,"even":"horizontal","odd":"vertical"})");
  EXPECT_EQ(read_row_access(json_file("stand_in.json", stand_in.identity())), stand_in);
  EXPECT_EQ(resolve_row_access("default"), stand_in);
  EXPECT_EQ(resolve_row_access(""), stand_in);
  const auto owner = read_row_access(json_file(
      "owner.json",
      R"({"schema": 1, "name": "router \"v2\"", "version": "2026-10", "index_base": 1, "even": "vertical", "odd": "horizontal"})"));
  EXPECT_EQ(owner.name, "router \"v2\"");
  EXPECT_EQ(owner.index_base, 1u);
  EXPECT_EQ(owner.at(0), horizontal);
  EXPECT_EQ(resolve_row_access(json_file("owner2.json", owner.identity())), owner);
  for (auto changed : {owner, stand_in}) {
    changed.version += "x";
    EXPECT_NE(changed.identity(), owner.identity());
    EXPECT_NE(changed.identity(), stand_in.identity());
  }
}
TEST(RowAccess, ReaderRefusesAnythingButTheSchema) {
  const std::string ok = R"("schema": 1, "name": "n", "version": "1", "even": "horizontal", "odd": "vertical")";
  EXPECT_NO_THROW(read_row_access(json_file("ok.json", "{" + ok + "}")));
  for (const auto& bad : {
           "{" + ok + ", \"extra\": 1}",
           "{" + ok + ", \"origin\": \"die\"}",
           "{" + ok + ", \"index_base\": -1}",
           std::string(R"({"schema": 2, "name": "n", "version": "1", "even": "horizontal", "odd": "vertical"})"),
           std::string(R"({"schema": 1, "name": "n", "version": "1", "even": "diagonal", "odd": "vertical"})"),
           std::string(R"({"schema": 1, "name": "", "version": "1", "even": "horizontal", "odd": "vertical"})"),
           std::string(R"({"schema": 1, "name": "n", "version": "1", "even": "horizontal"})"),
           std::string("[1]"),
           std::string("{"),
       }) {
    EXPECT_THROW(read_row_access(json_file("bad.json", bad)), std::invalid_argument) << bad;
  }
  EXPECT_THROW(read_row_access(json_file("bad.json", "{" + ok + "}") + ".missing"), std::invalid_argument);
}
}  // namespace livehd::physical
